package dev.industrialtechnology.client;
import net.minecraft.client.renderer.entity.Render;import net.minecraft.entity.Entity;import net.minecraft.util.ResourceLocation;import org.lwjgl.opengl.GL11;import dev.industrialtechnology.railway.*;
public final class RollingStockRenderer extends Render {
 public RollingStockRenderer(){shadowSize=1.5f;}@Override protected ResourceLocation getEntityTexture(Entity e){return RailMesh.MATERIALS;}
 @Override public void doRender(Entity raw,double x,double y,double z,float yaw,float partial){EntityRollingStock e=(EntityRollingStock)raw;GL11.glPushAttrib(GL11.GL_ALL_ATTRIB_BITS);GL11.glPushMatrix();try{bindTexture(RailMesh.MATERIALS);GL11.glColor4f(1,1,1,1);GL11.glEnable(org.lwjgl.opengl.GL12.GL_RESCALE_NORMAL);GL11.glDisable(GL11.GL_CULL_FACE);GL11.glTranslated(x,y,z);TrackWorld.Cursor c=TrackWorld.nearest(e.worldObj,e.posX,e.posY,e.posZ,2);boolean inside=net.minecraft.client.Minecraft.getMinecraft().thePlayer.ridingEntity==e&&net.minecraft.client.Minecraft.getMinecraft().gameSettings.thirdPersonView==0;boolean cab=inside&&e.stock.engine();if(inside&&e.stock==StockType.PASSENGER){GL11.glPushMatrix();GL11.glRotatef(-yaw,0,1,0);RailMesh.draw("passenger_inside");GL11.glPopMatrix();}else if(cab){GL11.glPushMatrix();GL11.glRotatef(-yaw,0,1,0);GL11.glTranslated(0,0,e.stock==StockType.STEAM?-5:e.stock.length*.34);RailMesh.draw("cab");double[] gauges={e.speed/Math.max(.01,e.stock.speed),e.stock==StockType.STEAM?e.temperature/300:e.energy/(double)Math.max(1,e.capacity()),e.stock==StockType.STEAM?e.pressure():e.speed/Math.max(.01,e.stock.speed)};for(int gauge=0;gauge<3;gauge++){GL11.glPushMatrix();GL11.glTranslated((gauge-1)*.5,2.34,1.1);GL11.glRotated(-110+Math.max(0,Math.min(1,gauges[gauge]))*220,0,1,0);RailMesh.box(0,0,.06,.014,.012,.13,4);GL11.glPopMatrix();}GL11.glPopMatrix();if(e.stock==StockType.STEAM){GL11.glPushMatrix();GL11.glRotatef(-yaw,0,1,0);RailMesh.draw("steam_front");GL11.glPopMatrix();}}else if(e.stock==StockType.AZ8A){part(e,c,8,"az8a_section",false);part(e,c,-8,"az8a_section",true);}else{GL11.glPushMatrix();bodyPose(e,c,0,e.stock.bogie,false);RailMesh.draw(new String[]{"steam","industrial","acs64","az8a_section","freight","passenger"}[e.stock.ordinal()]);GL11.glPopMatrix();}
 if(e.lights&&e.stock.engine()){GL11.glPushAttrib(GL11.GL_ALL_ATTRIB_BITS);GL11.glPushMatrix();try{GL11.glDisable(GL11.GL_LIGHTING);GL11.glColor4f(1,1,1,1);GL11.glRotatef(-yaw,0,1,0);double front=e.stock==StockType.STEAM?7.78:e.stock.length/2-.08;for(double xx:new double[]{-1,1})RailMesh.box(xx,1.56,front,.3,.21,.03,11);}finally{GL11.glPopMatrix();GL11.glPopAttrib();}}
 double wheel=(e.previousTravel+(e.travel-e.previousTravel)*partial)/(.49*2*Math.PI)*360;double[] offsets=e.stock==StockType.AZ8A?new double[]{-12,-4,4,12}:new double[]{-e.stock.bogie,e.stock.bogie};for(double offset:offsets){GL11.glPushMatrix();pose(e,c,offset,false);GL11.glTranslated(0,.62,0);RailMesh.draw("bogie");for(double zz:new double[]{-1.05,1.05})for(double xx:new double[]{-.78,.78}){GL11.glPushMatrix();GL11.glTranslated(xx,0,zz);GL11.glRotated(wheel,1,0,0);RailMesh.draw("wheel");GL11.glPopMatrix();}GL11.glPopMatrix();}
 if(e.stock==StockType.STEAM){GL11.glPushMatrix();GL11.glRotatef(-yaw,0,1,0);for(double zz:new double[]{0,2,4})for(double xx:new double[]{-1,1}){GL11.glPushMatrix();GL11.glTranslated(xx,.72,zz);GL11.glRotated(wheel,1,0,0);GL11.glScaled(1,1.4,1.4);RailMesh.draw("wheel");GL11.glPopMatrix();}for(double xx:new double[]{-1.17,1.17}){GL11.glPushMatrix();double a=Math.toRadians(wheel);GL11.glTranslated(xx,.72+Math.sin(a)*.35,2+Math.cos(a)*.35);RailMesh.draw("rod");GL11.glPopMatrix();}GL11.glPopMatrix();}
 }finally{GL11.glPopMatrix();GL11.glPopAttrib();}}
 private void part(EntityRollingStock e,TrackWorld.Cursor c,double off,String mesh,boolean reverse){GL11.glPushMatrix();bodyPose(e,c,off,4,reverse);RailMesh.draw(mesh);GL11.glPopMatrix();}
 private void bodyPose(EntityRollingStock e,TrackWorld.Cursor c,double off,double half,boolean reverse){if(c!=null){TrackWorld.Cursor a=c.copy(),b=c.copy();if(a.move(e.worldObj,off-half)&&b.move(e.worldObj,off+half)){double[] p=a.point(e.worldObj),q=b.point(e.worldObj);GL11.glTranslated((p[0]+q[0])/2-e.posX,(p[1]+q[1])/2-e.posY,(p[2]+q[2])/2-e.posZ);double dx=q[0]-p[0],dy=q[1]-p[1],dz=q[2]-p[2];double yaw=Math.toDegrees(Math.atan2(-dx,dz)),pitch=-Math.toDegrees(Math.atan2(dy,Math.sqrt(dx*dx+dz*dz)));GL11.glRotated(-yaw+(reverse?180:0),0,1,0);GL11.glRotated(pitch,1,0,0);return;}}pose(e,c,off,reverse);}
 private void pose(EntityRollingStock e,TrackWorld.Cursor c,double off,boolean reverse){double yaw=e.rotationYaw;if(c!=null){TrackWorld.Cursor q=c.copy();if(q.move(e.worldObj,off)){double[] p=q.point(e.worldObj);GL11.glTranslated(p[0]-e.posX,p[1]-e.posY,p[2]-e.posZ);yaw=q.yaw(e.worldObj);}}else{double a=Math.toRadians(e.rotationYaw);GL11.glTranslated(-Math.sin(a)*off,0,Math.cos(a)*off);}GL11.glRotated(-yaw+(reverse?180:0),0,1,0);}
}
